const rawText = $input.first().json["Paste The JSON"]; 
const payload = JSON.parse(rawText);
const goalsData = payload.goals || {};
const splitItems = [];

for (const [name, details] of Object.entries(goalsData)) {
  const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
  const shortHash = Math.random().toString(36).substring(2, 6).toUpperCase();
  splitItems.push({
    json: {
      "Task ID": `TSK-${dateStr}-${name.substring(0,3).toUpperCase()}-${shortHash}`,
      "Date": new Date().toLocaleDateString('en-GB'),
      "Task Description": details.goal || details,
      "Assigned To": name,
      "Assigned By": "Manager",
      "Deadline": details.deadline || "",
      "Status": "Pending",
      "Reason": "",
      "Source": "Daily Goals Input",
      "Updated By": "n8n Automation",
      "Last Updated": new Date().toISOString()
    }
  });
}
return splitItems;

