const rawInput = $('On form submission').first().json['Paste The JSON'];
let finalTranscript = "";
let individualUpdates = {};

try {
    const parsedData = JSON.parse(rawInput);
    finalTranscript = parsedData.transcript || "";
    individualUpdates = parsedData.individual_updates || {};
} catch (e) {
    finalTranscript = rawInput;
}

const today = new Date().toLocaleDateString('en-GB');
let dailyContext = [];
let monthlyContext = [];

try {
    const ganesh = $('Fetch Ganesh Context').all() || [];
    const shreyash = $('Fetch Shreyash Context').all() || [];
    const shruti = $('Fetch Shruti Context').all() || [];
    const vaishnavi = $('Fetch Vaishnavi Context').all() || [];

    // We only pass items that have actual data (i.e., not empty alwaysOutputData placeholders)
    dailyContext = [...ganesh, ...shreyash, ...shruti, ...vaishnavi]
      .map(item => item.json)
      .filter(item => Object.keys(item).length > 0 && item["Task ID"]);
} catch(e) {}

try {
    const rawMonthly = $('Fetch Monthly Context').all() || [];
    monthlyContext = rawMonthly.map(item => item.json).filter(item => Object.keys(item).length > 0 && item["Goal ID"]);
} catch(e) {}

return [{
  json: {
    transcript: finalTranscript,
    individual_updates: individualUpdates,
    daily_context: dailyContext,
    monthly_context: monthlyContext
  }
}];

const text = $input.first().json.text || "";
let cleanText = text;

// Find the first { and last } to robustly extract the JSON
const firstBrace = cleanText.indexOf('{');
const lastBrace = cleanText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
    cleanText = cleanText.substring(firstBrace, lastBrace + 1);
}

let parsed = { Tasks: [], Reports: [] };
try { 
    parsed = JSON.parse(cleanText); 
} catch (e) { 
    console.log("LLM Parse Error:", e); 
}
const tasks = parsed.Tasks || [];

return tasks.map(t => {
    const safeName = (t.Assigned_To || "UNK").substring(0,3).toUpperCase();
    const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, '');
    const shortHash = Math.random().toString(36).substring(2, 6).toUpperCase();

    // Use the existing Task_ID provided by LLM or generate a new one if blank
    const taskId = (t.Task_ID && t.Task_ID.trim() !== "") ? t.Task_ID : `TSK-${dateStr}-${safeName}-${shortHash}`;

    return { 
      json: {
        "Task ID": taskId,
        "Date": new Date().toLocaleDateString('en-GB'),
        "Task Description": t.Task_Description || "-",
        "Assigned To": t.Assigned_To || "-",
        "Assigned By": t.Assigned_By || "-",
        "Deadline": t.Deadline || "",
        "Status": t.Status || "Pending",
        "Reason": t.Reason || "",
        "Source": t.Source || "Meeting Transcript",
        "Updated By": "n8n Automation",
        "Last Updated": new Date().toISOString()
      }
    };
});

